import SwiftUI
import AppKit
import AVFoundation
import UniformTypeIdentifiers
import UserNotifications

// NeoTorrentSession is generated by UniFFI. The underlying Rust handle is
// `Send + Sync`, so it's safe to share across actor boundaries. Promise that
// to Swift here so we can pass it freely between MainActor and Tasks.
extension NeoTorrentSession: @unchecked Sendable {}
extension TorrentSnapshot: @unchecked Sendable {}
extension TorrentFile: @unchecked Sendable {}

@MainActor
final class AppDelegate: NSObject, NSApplicationDelegate, UNUserNotificationCenterDelegate {
    let prefs = Preferences()
    let posters = PosterStore()
    let store = TorrentStore()
    let sessionHolder = SessionHolder()
    var openMainWindow: (() -> Void)?

    func applicationWillFinishLaunching(_ notification: Notification) {
        // Set before launch finishes so a notification click that launches
        // the app is delivered.
        UNUserNotificationCenter.current().delegate = self
    }

    func applicationDidFinishLaunching(_ notification: Notification) {
        Task { await sessionHolder.start(prefs: prefs, store: store, posters: posters) }
    }

    func applicationShouldTerminateAfterLastWindowClosed(_ sender: NSApplication) -> Bool {
        false
    }

    func applicationShouldHandleReopen(_ sender: NSApplication, hasVisibleWindows flag: Bool) -> Bool {
        if !flag { showMainWindow() }
        return true
    }

    func applicationShouldTerminate(_ sender: NSApplication) -> NSApplication.TerminateReply {
        store.stopPlayback()
        guard let session = sessionHolder.session else { return .terminateNow }
        // Let librqbit stop its tasks, but never hold up quitting for long.
        Task {
            await session.shutdown()
            sender.reply(toApplicationShouldTerminate: true)
        }
        Task {
            try? await Task.sleep(for: .seconds(3))
            sender.reply(toApplicationShouldTerminate: true)
        }
        return .terminateLater
    }

    func showMainWindow() {
        NSApp.activate()
        openMainWindow?()
    }

    // Show completion banners even while the app is frontmost.
    nonisolated func userNotificationCenter(
        _ center: UNUserNotificationCenter,
        willPresent notification: UNNotification
    ) async -> UNNotificationPresentationOptions {
        [.banner]
    }

    // Clicking a notification brings the main window back.
    nonisolated func userNotificationCenter(
        _ center: UNUserNotificationCenter,
        didReceive response: UNNotificationResponse
    ) async {
        await MainActor.run { self.showMainWindow() }
    }
}

@main
struct NeoTorrentApp: App {
    @NSApplicationDelegateAdaptor(AppDelegate.self) private var appDelegate

    var body: some Scene {
        Window("NeoTorrent", id: "main") {
            ContentView()
                .environment(appDelegate.sessionHolder)
                .environment(appDelegate.prefs)
                .environment(appDelegate.posters)
                .environment(appDelegate.store)
                .frame(minWidth: 640, idealWidth: 820, minHeight: 320, idealHeight: 380)
                .modifier(OpenWindowRegistrar { appDelegate.openMainWindow = $0 })
                .onOpenURL { url in
                    appDelegate.sessionHolder.handleOpenURL(url)
                }
        }
        .windowStyle(.titleBar)
        .windowToolbarStyle(.unified)
        .defaultLaunchBehavior(.presented)
        .commands {
            AppCommands(sessionHolder: appDelegate.sessionHolder)
        }

        Settings {
            SettingsView()
                .environment(appDelegate.prefs)
        }
        .windowResizability(.contentSize)
    }
}

/// Hands the scene's `openWindow` action to AppKit-side code (Dock reopen,
/// notification clicks) that has no SwiftUI environment of its own.
private struct OpenWindowRegistrar: ViewModifier {
    @Environment(\.openWindow) private var openWindow
    let register: (@escaping () -> Void) -> Void

    func body(content: Content) -> some View {
        content.onAppear {
            let openWindow = openWindow
            register { openWindow(id: "main") }
        }
    }
}

private struct AppCommands: Commands {
    let sessionHolder: SessionHolder
    @Environment(\.openWindow) private var openWindow

    var body: some Commands {
        CommandGroup(replacing: .appInfo) {
            Button("About NeoTorrent") { showAboutPanel() }
        }
        CommandGroup(after: .newItem) {
            Button("Open Torrent…") {
                openWindow(id: "main")
                sessionHolder.pickAndAddTorrentFiles()
            }
            .keyboardShortcut("o", modifiers: [.command])
            Button("Add from Clipboard") {
                openWindow(id: "main")
                sessionHolder.addFromClipboard()
            }
            .keyboardShortcut("v", modifiers: [.command, .shift])
        }
    }

    private func showAboutPanel() {
        let para = NSMutableParagraphStyle()
        para.alignment = .center
        para.paragraphSpacing = 4
        para.lineSpacing = 2

        let tagline: [NSAttributedString.Key: Any] = [
            .font: NSFont.systemFont(ofSize: 11, weight: .regular),
            .foregroundColor: NSColor.secondaryLabelColor,
            .paragraphStyle: para
        ]
        let linkStyle: [NSAttributedString.Key: Any] = [
            .font: NSFont.systemFont(ofSize: 11, weight: .medium),
            .foregroundColor: NSColor.linkColor,
            .underlineStyle: 0,
            .underlineColor: NSColor.clear,
            .paragraphStyle: para
        ]

        let credits = NSMutableAttributedString()
        credits.append(NSAttributedString(
            string: "Native macOS BitTorrent client\n\n",
            attributes: tagline
        ))
        credits.append(NSAttributedString(
            string: "Github",
            attributes: linkStyle.merging([.link: URL(string: "https://github.com/lodev09/neotorrent")!]) { $1 }
        ))
        credits.append(NSAttributedString(string: "  ·  ", attributes: tagline))
        credits.append(NSAttributedString(
            string: "@lodev09",
            attributes: linkStyle.merging([.link: URL(string: "https://github.com/lodev09")!]) { $1 }
        ))

        NSApplication.shared.orderFrontStandardAboutPanel(options: [
            .credits: credits
        ])
    }
}

struct PendingTorrent: Identifiable {
    let id = UUID()
    var name: String
    var uri: String
    var infoHash: String?
    var torrentID: UInt64?
}

enum AddTorrentError: LocalizedError {
    case alreadyAdded(name: String)
    case alreadyAdding(name: String)
    case nothingToAdd

    var errorDescription: String? {
        switch self {
        case .alreadyAdded(let name): return "“\(name)” is already in your list"
        case .alreadyAdding(let name): return "“\(name)” is already being added"
        case .nothingToAdd: return "No magnet link or .torrent file found."
        }
    }
}

/// The Rust-side message for engine errors; `localizedDescription` otherwise.
func errorDetail(_ error: Error) -> String {
    guard let e = error as? NeoTorrentError else { return error.localizedDescription }
    switch e {
    case .InvalidMagnet(let message), .Session(let message), .Cancelled(let message):
        return message
    }
}

func friendlyAddError(_ error: Error) -> String {
    if let e = error as? AddTorrentError {
        return e.errorDescription ?? "Couldn't add torrent."
    }
    let lower = errorDetail(error).lowercased()
    if lower.contains("invalid magnet") || lower.contains("missing xt") || lower.contains("not a magnet")
        || lower.contains("not a valid magnet") {
        return "That doesn't look like a valid magnet link."
    }
    if lower.contains("not a .torrent file") {
        return "That isn't a .torrent file."
    }
    if lower.contains("too large") {
        return "That .torrent file is too large."
    }
    if lower.contains("no such file") || lower.contains("error reading local file") {
        return "Couldn't read that .torrent file."
    }
    if lower.contains("invalid torrent") || lower.contains("bencode") || lower.contains("decode") {
        return "That .torrent file is malformed."
    }
    if lower.contains("invalid url") || lower.contains("invalid uri") || lower.contains("invalid file url") {
        return "That URL doesn't look right."
    }
    if lower.contains("timeout") || lower.contains("timed out") {
        return "Timed out reaching the tracker."
    }
    if lower.contains("network") || lower.contains("connection") || lower.contains("dns") {
        return "Network error — check your connection."
    }
    return "Couldn't add torrent."
}

@MainActor
@Observable
final class SessionHolder {
    var session: NeoTorrentSession?
    var startupError: String?
    /// Transient banner for failed user actions.
    var errorMessage: String?
    var pendingAdds: [PendingTorrent] = []
    private var prefs: Preferences?
    private var preStartQueue: [String] = []
    private var isStarting = false

    private static let pendingURIsKey = "pendingURIs"

    private static let stateDir = (NSHomeDirectory() as NSString)
        .appendingPathComponent("Library/Application Support/neotorrent")
    private static let logFile = (NSHomeDirectory() as NSString)
        .appendingPathComponent("Library/Logs/NeoTorrent/neotorrent.log")

    func start(prefs: Preferences, store: TorrentStore, posters: PosterStore) async {
        guard session == nil, !isStarting else { return }
        isStarting = true
        defer { isStarting = false }
        startupError = nil
        self.prefs = prefs
        let downloadDir = prefs.downloadDir
        try? FileManager.default.createDirectory(atPath: downloadDir, withIntermediateDirectories: true)
        do {
            let s = try await NeoTorrentSession(
                downloadDir: downloadDir,
                stateDir: Self.stateDir,
                logFile: Self.logFile
            )
            session = s
            prefs.attach(s)
            store.start(sessionHolder: self, prefs: prefs, posters: posters)
            // Magnets still resolving when the app last quit, then anything
            // opened while the engine was starting.
            let resumed = UserDefaults.standard.stringArray(forKey: Self.pendingURIsKey) ?? []
            var seen: Set<String> = []
            let uris = (resumed + preStartQueue).filter { seen.insert($0).inserted }
            preStartQueue.removeAll()
            add(uris: uris)
        } catch {
            startupError = "The torrent engine failed to start: \(errorDetail(error))"
        }
    }

    /// Adds each URI concurrently; failures surface in `errorMessage`.
    func add(uris: [String]) {
        for uri in uris {
            Task {
                do { try await add(uri: uri) }
                catch { errorMessage = friendlyAddError(error) }
            }
        }
    }

    @discardableResult
    func add(uri: String) async throws -> UInt64? {
        guard let session else {
            preStartQueue.append(uri)
            return nil
        }
        let infoHash = uri.hasPrefix("magnet:") ? (try? parseMagnet(uri: uri))?.infoHash.lowercased() : nil
        if let infoHash, let other = pendingAdds.first(where: { $0.infoHash == infoHash }) {
            throw AddTorrentError.alreadyAdding(name: other.name)
        }
        let entry = PendingTorrent(name: displayName(for: uri), uri: uri, infoHash: infoHash)
        pendingAdds.append(entry)
        persistPending()
        defer { persistPending() }
        do {
            let added = try await session.addTorrent(
                uri: uri,
                outputFolder: prefs?.downloadDir,
                token: entry.id.uuidString
            )
            guard pendingAdds.contains(where: { $0.id == entry.id }) else {
                // Cancelled after the engine had already added it.
                if !added.alreadyManaged {
                    try? await session.remove(id: added.id, deleteFiles: false)
                }
                return nil
            }
            if added.alreadyManaged {
                pendingAdds.removeAll { $0.id == entry.id }
                let name = session.list().first { $0.id == added.id }?.name ?? entry.name
                throw AddTorrentError.alreadyAdded(name: name)
            }
            if let i = pendingAdds.firstIndex(where: { $0.id == entry.id }) {
                pendingAdds[i].torrentID = added.id
            }
            return added.id
        } catch NeoTorrentError.Cancelled {
            return nil
        } catch {
            pendingAdds.removeAll { $0.id == entry.id }
            throw error
        }
    }

    func cancelPending(_ pendingID: UUID) {
        guard let entry = pendingAdds.first(where: { $0.id == pendingID }) else { return }
        pendingAdds.removeAll { $0.id == pendingID }
        persistPending()
        guard let session else { return }
        if let torrentID = entry.torrentID {
            Task { try? await session.remove(id: torrentID, deleteFiles: false) }
        } else {
            session.cancelAdd(token: pendingID.uuidString)
        }
    }

    func reconcilePending(against torrentIDs: Set<UInt64>) {
        pendingAdds.removeAll { p in
            guard let tid = p.torrentID else { return false }
            return torrentIDs.contains(tid)
        }
    }

    func handleOpenURL(_ url: URL) {
        let uris = Self.torrentURIs(in: [url.absoluteString])
        guard !uris.isEmpty else { return }
        errorMessage = nil
        add(uris: uris)
    }

    func pickAndAddTorrentFiles() {
        let panel = NSOpenPanel()
        if let type = UTType(filenameExtension: "torrent") {
            panel.allowedContentTypes = [type]
        }
        panel.canChooseFiles = true
        panel.canChooseDirectories = false
        panel.allowsMultipleSelection = true
        panel.message = "Choose .torrent file(s) to add"
        guard panel.runModal() == .OK else { return }
        errorMessage = nil
        add(uris: panel.urls.map(\.path))
    }

    func addFromClipboard() {
        let pb = NSPasteboard.general
        var strings: [String] = []
        if let urls = pb.readObjects(forClasses: [NSURL.self]) as? [URL] {
            strings.append(contentsOf: urls.map(\.absoluteString))
        }
        if let text = pb.readObjects(forClasses: [NSString.self]) as? [String] {
            strings.append(contentsOf: text)
        }
        addDropped(strings)
    }

    /// Add whatever magnets / .torrent files / URLs `strings` contain.
    func addDropped(_ strings: [String]) {
        let uris = Self.torrentURIs(in: strings)
        guard !uris.isEmpty else {
            errorMessage = friendlyAddError(AddTorrentError.nothingToAdd)
            return
        }
        errorMessage = nil
        add(uris: uris)
    }

    /// Magnet links, http(s) URLs and local .torrent files found in pasted
    /// or dropped text (one per line), de-duplicated by info hash.
    nonisolated static func torrentURIs(in strings: [String]) -> [String] {
        var seen: Set<String> = []
        var result: [String] = []
        for line in strings.flatMap({ $0.components(separatedBy: .newlines) }) {
            let s = line.trimmingCharacters(in: .whitespaces)
            let url = URL(string: s)
            let uri: String?
            if s.lowercased().hasPrefix("magnet:") {
                uri = s
            } else if let url, url.isFileURL {
                uri = url.pathExtension.lowercased() == "torrent" ? url.path : nil
            } else if s.hasPrefix("/") {
                uri = s.lowercased().hasSuffix(".torrent") ? s : nil
            } else if let scheme = url?.scheme?.lowercased(), scheme == "http" || scheme == "https" {
                uri = s
            } else {
                uri = nil
            }
            guard let uri else { continue }
            let key = (try? parseMagnet(uri: uri))?.infoHash.lowercased() ?? uri
            if seen.insert(key).inserted { result.append(uri) }
        }
        return result
    }

    private func persistPending() {
        let uris = pendingAdds.filter { $0.torrentID == nil }.map(\.uri)
        UserDefaults.standard.set(uris, forKey: Self.pendingURIsKey)
    }

    private func displayName(for uri: String) -> String {
        if uri.hasPrefix("magnet:") {
            if let parsed = try? parseMagnet(uri: uri) {
                if let n = parsed.displayName, !n.isEmpty { return n }
                return "Magnet (\(parsed.infoHash.prefix(8))…)"
            }
            return "Magnet"
        }
        if let url = URL(string: uri), url.scheme == "http" || url.scheme == "https" {
            return url.lastPathComponent.isEmpty ? (url.host ?? uri) : url.lastPathComponent
        }
        return URL(fileURLWithPath: uri).deletingPathExtension().lastPathComponent
    }
}

@MainActor
@Observable
final class PosterStore {
    private(set) var images: [String: NSImage] = [:]
    private var inFlight: Set<String> = []
    private var nextRetry: [String: Date] = [:]
    private var attempts: [String: Int] = [:]

    /// Containers AVFoundation can decode a frame from.
    nonisolated static let posterExtensions: Set<String> = ["mp4", "m4v", "mov"]
    private static let maxAttempts = 5

    private static let cacheDir: URL = {
        let url = URL(fileURLWithPath: NSHomeDirectory())
            .appendingPathComponent("Library/Application Support/neotorrent/posters", isDirectory: true)
        try? FileManager.default.createDirectory(at: url, withIntermediateDirectories: true)
        return url
    }()

    func image(for infoHash: String) -> NSImage? {
        images[infoHash.lowercased()]
    }

    /// Whether `ensure` could still produce a poster for this torrent.
    func wantsPoster(for infoHash: String) -> Bool {
        let key = infoHash.lowercased()
        return images[key] == nil && !inFlight.contains(key) && (attempts[key] ?? 0) < Self.maxAttempts
            && (nextRetry[key] ?? .distantPast) <= Date()
    }

    func ensure(infoHash: String, fileURL: URL) {
        let key = infoHash.lowercased()
        guard wantsPoster(for: key) else { return }
        let cached = Self.cacheDir.appendingPathComponent("\(key).jpg")
        if let img = NSImage(contentsOf: cached) {
            images[key] = img
            return
        }
        inFlight.insert(key)
        attempts[key, default: 0] += 1
        Task.detached(priority: .utility) {
            let img = await Self.generate(source: fileURL, output: cached)
            await MainActor.run {
                self.inFlight.remove(key)
                if let img {
                    self.images[key] = img
                    self.nextRetry.removeValue(forKey: key)
                } else {
                    self.nextRetry[key] = Date().addingTimeInterval(30)
                }
            }
        }
    }

    func remove(infoHash: String) {
        let key = infoHash.lowercased()
        images.removeValue(forKey: key)
        attempts.removeValue(forKey: key)
        nextRetry.removeValue(forKey: key)
        try? FileManager.default.removeItem(at: Self.cacheDir.appendingPathComponent("\(key).jpg"))
    }

    nonisolated private static func generate(source: URL, output: URL) async -> NSImage? {
        let asset = AVURLAsset(url: source)
        let gen = AVAssetImageGenerator(asset: asset)
        gen.appliesPreferredTrackTransform = true
        gen.maximumSize = CGSize(width: 900, height: 900)
        gen.requestedTimeToleranceBefore = .positiveInfinity
        gen.requestedTimeToleranceAfter = .positiveInfinity
        do {
            let duration = try await asset.load(.duration)
            let secs = max(1.0, CMTimeGetSeconds(duration) * 0.1)
            let time = CMTime(seconds: secs, preferredTimescale: 600)
            let (cg, _) = try await gen.image(at: time)
            let img = NSImage(cgImage: cg, size: NSSize(width: cg.width, height: cg.height))
            if let jpg = NSBitmapImageRep(cgImage: cg).representation(using: .jpeg, properties: [.compressionFactor: 0.85]) {
                try? jpg.write(to: output, options: .atomic)
            }
            return img
        } catch {
            return nil
        }
    }
}
